sp_widget.script:
(function() { data.questions = []; data.sectionId = $sp.getParameter("section_id") || "";
  try { if (!data.sectionId) return;
    if (input && input.action === "add_question") { var qGr = new GlideRecord("x_1433041_identi_0_question"); qGr.initialize(); qGr.setValue("section", data.sectionId); qGr.setValue("text", input.text); qGr.setValue("question_type", input.question_type || "text"); qGr.setValue("mandatory", input.mandatory || false); qGr.setValue("order", input.order_num || 100); qGr.insert(); }
    var gr = new GlideRecord("x_1433041_identi_0_question"); gr.addQuery("section", data.sectionId); gr.orderBy("order"); gr.setLimit(100); gr.query();
    while (gr.next()) { data.questions.push({ sys_id: gr.getValue("sys_id"), text: gr.getValue("text"), question_type: gr.getDisplayValue("question_type"), mandatory: gr.getValue("mandatory") === "1", order: gr.getValue("order") }); }
  } catch (e) { gs.error("IBAR Question Form widget error: " + e.message); }
})();
